const input = $input.first()?.json ?? {};
if (input.input === undefined || input.input === null || input.input === '') {
  throw new Error('input is required');
}
const request = {
  model: '__CODEX_RELAY_MODEL__',
  input: input.input,
  max_output_tokens: Math.max(16, Math.min(32768, Number(input.max_output_tokens ?? 4096))),
  store: false,
};
if (typeof input.instructions === 'string' && input.instructions.trim()) request.instructions = input.instructions.trim();
if (Array.isArray(input.tools) && input.tools.length) request.tools = input.tools;
if (input.tool_choice !== undefined) request.tool_choice = input.tool_choice;
if (typeof input.parallel_tool_calls === 'boolean') request.parallel_tool_calls = input.parallel_tool_calls;
if (input.reasoning && typeof input.reasoning === 'object') request.reasoning = input.reasoning;
if (input.text && typeof input.text === 'object') request.text = input.text;
if (input.metadata && typeof input.metadata === 'object') request.metadata = input.metadata;
return [{ json: { ...input, request } }];

const input = $('Build Responses Request').item.json;
const received = $input.first()?.json ?? {};
const knownPayloadKeys = new Set(['output', 'output_text', 'choices', 'status', 'incomplete_details', 'error', 'id', 'model']);
const isObject = (value) => value && typeof value === 'object' && !Array.isArray(value);
const hasPayloadShape = (value) => isObject(value) && [...knownPayloadKeys].some((key) => Object.prototype.hasOwnProperty.call(value, key));
const parseBody = (value) => {
  if (typeof value !== 'string') return value;
  const trimmed = value.trim();
  if (!trimmed) return value;
  try { return JSON.parse(trimmed); } catch { return value; }
};
let response = received;
let relayResponseShape = 'direct';
for (let depth = 0; depth < 4 && isObject(response) && !hasPayloadShape(response); depth += 1) {
  let key = null;
  if (Object.prototype.hasOwnProperty.call(response, 'body')) key = 'body';
  else if (Object.prototype.hasOwnProperty.call(response, 'data')) key = 'data';
  else if (Object.prototype.hasOwnProperty.call(response, 'response')) key = 'response';
  if (!key) break;
  const nested = parseBody(response[key]);
  if (nested === response[key] && typeof nested === 'string') break;
  response = nested;
  relayResponseShape = relayResponseShape === 'direct' ? key : relayResponseShape + '.' + key;
}
if (!isObject(response)) response = {};
const output = Array.isArray(response.output) ? response.output : [];
const contentToText = (content) => {
  if (typeof content === 'string') return content;
  if (!Array.isArray(content)) return '';
  return content.map((part) => typeof part === 'string' ? part : String(part?.text ?? part?.content ?? '')).join('');
};
const nestedOutputText = output.flatMap((item) => Array.isArray(item?.content) ? item.content : []).filter((item) => item && typeof item.text === 'string' && ['output_text', 'text'].includes(String(item.type ?? ''))).map((item) => String(item.text)).join('');
const directOutputText = typeof response.output_text === 'string' ? response.output_text : '';
const compatibleOutputText = Array.isArray(response.choices) ? response.choices.map((item) => contentToText(item?.message?.content ?? item?.text ?? '')).join('') : '';
const outputText = [nestedOutputText, directOutputText, compatibleOutputText].find((value) => String(value ?? '').trim()) ?? '';
const toolCalls = output.filter((item) => item?.type === 'function_call').map((item) => {
  let argumentsValue = item.arguments ?? '';
  try { argumentsValue = JSON.parse(argumentsValue); } catch {}
  return { call_id: item.call_id, name: item.name, arguments: argumentsValue, status: item.status };
});
const relayKeys = isObject(received) ? Object.keys(received).slice(0, 40) : [];
return [{ json: {
  ...input,
  response_id: response.id,
  model: response.model,
  status: response.status ?? received.status ?? received.statusCode ?? null,
  incomplete_details: response.incomplete_details ?? null,
  output_text: outputText,
  output_types: output.map((item) => ({ type: String(item?.type ?? ''), content_types: Array.isArray(item?.content) ? item.content.map((part) => String(part?.type ?? '')) : [] })),
  tool_calls: toolCalls,
  output,
  usage: response.usage ?? {},
  error: response.error ?? (received.error ?? null),
  relay_response_shape: relayResponseShape,
  relay_response_keys: relayKeys,
} }];
